(7670564, 1251953, 30049, '<td valign="top">That''s a very clear, crisp photo for something you''d see if you close your eyes.  Fun looking puzzle.</td>', 'That''s a very clear, crisp photo for something you''d see if you close your eyes.  Fun looking puzzle.', '2020-07-22 20:35:12.000000', NULL, 1),
(7670565, 1252160, 30049, '<td valign="top">It''s possible I suppose.  Seems a bit tidy for something you''d really see when you close your eyes.</td>', 'It''s possible I suppose.  Seems a bit tidy for something you''d really see when you close your eyes.', '2020-07-22 20:36:21.000000', NULL, 1),
