(7670568, 1252165, 30049, '<td valign="top">Yep.  Now this is possible.  Sleepy, yet interesting to look at.  Good luck!</td>', 'Yep.  Now this is possible.  Sleepy, yet interesting to look at.  Good luck!', '2020-07-22 20:39:06.000000', NULL, 1),
(7670569, 1251893, 30049, '<td valign="top">A bit bright for something you''d see when you close your eyes IMO.  As a regular photo, putting the challenge theme aside, it''s somewhat of a snapshot.</td>', 'A bit bright for something you''d see when you close your eyes IMO.  As a regular photo, putting the challenge theme aside, it''s somewhat of a snapshot.', '2020-07-22 20:40:14.000000', NULL, 1),
(7670570, 1252144, 30049, '<td valign="top">The cat I could see, maybe.  The added moon seems totally unrelated and out of place.</td>', 'The cat I could see, maybe.  The added moon seems totally unrelated and out of place.', '2020-07-22 20:41:00.000000', NULL, 1),
(7670571, 1252140, 30049, '<td valign="top">Ok.  Abstract enough to fit.  An interesting one at that.  Nearly something you might see when you close your eyes.  Maybe.</td>', 'Ok.  Abstract enough to fit.  An interesting one at that.  Nearly something you might see when you close your eyes.  Maybe.', '2020-07-22 20:42:13.000000', NULL, 1),
(7670572, 1252159, 30049, '<td valign="top">This has a dark enough theme to be a consideration.  The title is perfect.  Tough challenge.  Good luck!</td>', 'This has a dark enough theme to be a consideration.  The title is perfect.  Tough challenge.  Good luck!', '2020-07-22 20:43:18.000000', NULL, 1),
(7670573, 1251805, 30049, '<td valign="top">You see yourself?  I don''t understand the concept of this image or how it fits with what you would see when you close your eyes. ???  It''s fun, but very bright!</td>', 'You see yourself?  I don''t understand the concept of this image or how it fits with what you would see when you close your eyes. ???  It''s fun, but very bright!', '2020-07-22 20:45:25.000000', NULL, 1),
(7670574, 1252046, 30049, '<td valign="top">Had one too many, eh?  LOL  Yes, I could see this as a possibility for what someone could see when they close their eyes.  Interesting take on the challenge, and I''m happy to see it!  Good luck.</td>', 'Had one too many, eh?  LOL  Yes, I could see this as a possibility for what someone could see when they close their eyes.  Interesting take on the challenge, and I''m happy to see it!  Good luck.', '2020-07-22 20:46:45.000000', NULL, 1),
(7670575, 1252094, 30049, '<td valign="top">Dark enough.  Perhaps a bit too crisp for something you might actually see when you close your eyes, but it seems hard for "photographers" here to forego sharpness for one challenge.  Good luck.  It is interesting to look at.</td>', 'Dark enough.  Perhaps a bit too crisp for something you might actually see when you close your eyes, but it seems hard for "photographers" here to forego sharpness for one challenge.  Good luck.  It is interesting to look at.', '2020-07-22 20:48:03.000000', NULL, 1),
