(7670579, 1252141, 30049, '<td valign="top">Different world indeed!  If I squint I can kind of see this floating in front of my eyelids.  :-)  Good luck.</td>', 'Different world indeed!  If I squint I can kind of see this floating in front of my eyelids.  :-)  Good luck.', '2020-07-22 20:57:12.000000', NULL, 1),
(7670580, 1252133, 30049, '<td valign="top">Very pretty.  Not something I''d first think of for the theme of this challenge however.</td>', 'Very pretty.  Not something I''d first think of for the theme of this challenge however.', '2020-07-22 20:58:02.000000', NULL, 1),
