(7670583, 1252006, 30049, '<td valign="top">Invert this into a negative and I could see it.  Bit bright as it is.</td>', 'Invert this into a negative and I could see it.  Bit bright as it is.', '2020-07-22 21:01:10.000000', NULL, 1),
(7670584, 1252169, 30049, '<td valign="top">This is pleasing.  Definitely "Extended Editing", but I get that for this challenge theme.  Still a tad bit sharp for something you''d see with your eyes closed but the swirl helps.  Good luck.</td>', 'This is pleasing.  Definitely "Extended Editing", but I get that for this challenge theme.  Still a tad bit sharp for something you''d see with your eyes closed but the swirl helps.  Good luck.', '2020-07-22 21:03:38.000000', NULL, 1),
(7670585, 1252018, 30049, '<td valign="top">More of a melt than a blur.  :)  It is interesting though and not another bright, pretty picture.  Thanks for using some creativity in line with the challenge theme.  Good luck.</td>', 'More of a melt than a blur.  :)  It is interesting though and not another bright, pretty picture.  Thanks for using some creativity in line with the challenge theme.  Good luck.', '2020-07-22 21:05:20.000000', NULL, 1),
(7670586, 1252057, 30049, '<td valign="top">Right you are!  Kudos for having the courage to enter an image that really does seem like something you''d see when you close your eyes.  Perhaps after an evening watching some firework celebrations?  :-P</td>', 'Right you are!  Kudos for having the courage to enter an image that really does seem like something you''d see when you close your eyes.  Perhaps after an evening watching some firework celebrations?  :-P', '2020-07-22 21:07:24.000000', NULL, 1),
(7670587, 1252102, 30049, '<td valign="top">Yep.  I agree, mostly.  A bit neat, but I like the concept and your courage to enter something non-traditional.  Good luck.</td>', 'Yep.  I agree, mostly.  A bit neat, but I like the concept and your courage to enter something non-traditional.  Good luck.', '2020-07-22 21:09:04.000000', NULL, 1),
